static void mnote_dump(ExifData *data) {
    ExifMnoteData *mn = exif_data_get_mnote_data(data);
    if (mn) {
        int num = exif_mnote_data_count(mn);
        for (int i=0; i < num; ++i) {
            char buf[1024];
            exif_mnote_data_get_value(mn, i, buf, sizeof(buf));
