  exif_data_foreach_content(data, data_func, NULL);
}

int main(int argc, char** argv) {
  if (argc < 2) return 1;
  FILE* f = fopen(argv[1], "rb");
  if (!f) return 1;
  fseek(f, 0, SEEK_END);
  long sz = ftell(f);
  fseek(f, 0, SEEK_SET);
  uint8_t* buf = (uint8_t*)malloc(sz);
  fread(buf, 1, sz, f);
  fclose(f);
  auto image = exif_data_new_from_data(buf, sz);
  if (image) {
    exif_data_get_mnote_data(image);
    data_dump(image);
    mnote_dump(image);
    unsigned char *obuf;
    unsigned int osz;
    exif_data_save_data(image, &obuf, &osz);
